//! TypeScript export tests for the ops console generated-types pipeline.
//!
//! # The registry is manual, so it can be incomplete
//!
//! [`ops_console_wire_types`] is a hand-maintained list of `push_type::<T>`
//! calls. Adding a field of a NEW type to an already-listed type emits a
//! reference to that new type without emitting its declaration, and the result
//! is a generated file that does not compile — `error TS2304: Cannot find name`.
//!
//! That happened on 2026-07-30: `DescribeWorkflowResponse` gained
//! `unserved: Vec<UnservedActivity>` and nothing added `UnservedActivity` to the
//! list. `cargo test --workspace` was fully green, because this file's export
//! test only WRITES the output and never inspected it. The break surfaced only
//! when someone ran the console's own `bun run typecheck`.
//!
//! [`assert_every_dependency_is_exported`] closes that: the check is computed
//! from ts-rs's OWN dependency graph for each pushed type, so it cannot drift
//! from what the emitter actually references, and it needs no hand-maintained
//! second list to stay true.

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

use ts_rs::{Config, TS};

use crate::{
    ActivityError, ActivityErrorKind, ActivityEvent, ActivityEventKind, ActivityId, AgentOutcome,
    ApprovalDecision, AttemptLiveness, CatchUpPolicy, ClusterCommand, ClusterDeployment,
    ClusterEvent, ClusterEventMeta, ClusterPeer, ClusterShard, ClusterSnapshot, ClusterStreamError,
    ClusterWorker, ContentType, CurrentStep, DeploymentAssociation, DescribeLiveResponse,
    DescribeWorkflowResponse, DesiredState, Event, EventEnvelope, HeartbeatNote, InjectPriority,
    InterventionCapabilities, InterventionCommand, InterventionKind, InterventionOutcome,
    InterventionPrimitive, LiveAttempt, MessageRole, NamespacePlacementWire, OpenStep,
    OverlapPolicy, PackageVersion, Payload, PayloadElision, ProgressDetail, PutOutcome,
    RunGeneration, RunId, ScheduleConfig, ScheduleId, SearchAttributeType, SearchAttributeValue,
    StepState, StopKind, TimerCancelCause, TimerId, TimerIdKind, TranscriptStreamHead,
    TranscriptTail, TriggerSpec, UnservedActivity, WithTimeoutOutcome, WorkerDeathReason,
    WorkerTransport, WorkflowError, WorkflowFilter, WorkflowId, WorkflowStatus, WorkflowSummary,
};

const OPS_CONSOLE_GENERATED_DIR: &str = "../../apps/aion-ops-console/src/types/generated";
/// Environment variable that turns this test from an assertion into a writer.
///
/// No regeneration opt-in existed anywhere in the workspace to match — the only
/// `AION_*` variables are runtime config and external-service test gates — so
/// this name is new, namespaced to the house `AION_` prefix, and named in the
/// failure message so it is discoverable from the failure alone.
const UPDATE_VAR: &str = "AION_UPDATE_BINDINGS";
/// The one command that regenerates. Named in the header of every generated
/// file, and in the failure below, so neither depends on a reader finding a
/// README.
const REGENERATE_COMMAND: &str =
    "AION_UPDATE_BINDINGS=1 cargo test -p aion-core export_ops_console_wire_types";
const GENERATED_HEADER: &str = concat!(
    "// This file is @generated by the aion-core/aion-proto ts-rs generated-types pipeline.\n",
    "// Do not edit by hand. Regenerate with:\n",
    "//   AION_UPDATE_BINDINGS=1 cargo test -p aion-core export_ops_console_wire_types\n",
    "// then commit the result. See apps/aion-ops-console/README.md.\n\n",
);
const TS_RS_HEADER: &str = concat!(
    "// This file was generated by [ts-rs](https://github.com/Aleph-Alpha/ts-rs). ",
    "Do not edit this file manually.\n\n",
);

/// The display-name key (#211) is emitted into the generated TypeScript as a
/// raw string literal, so it must contain nothing a literal would need escaped.
/// Renaming the key to something containing a quote, a backslash, or a newline
/// would otherwise emit TypeScript that does not parse — or, worse, one that
/// parses as something else. This pins the key's SHAPE, not its spelling: any
/// future rename is free, as long as it stays literal-safe.
#[test]
fn the_display_name_key_needs_no_escaping() {
    let key = crate::DISPLAY_NAME_ATTRIBUTE;
    assert!(
        !key.is_empty()
            && key
                .chars()
                .all(|character| !character.is_control() && character != '"' && character != '\\'),
        "`DISPLAY_NAME_ATTRIBUTE` is emitted verbatim into a TypeScript string literal and must \
         contain no quote, backslash, or control character: {key:?}"
    );
}

/// Asserts the committed ops-console bindings match what the exporter produces.
///
/// # This test does NOT write by default, and that is the whole point
///
/// It used to regenerate the file unconditionally and assert nothing. Two
/// consequences, both realised on 2026-07-30:
///
/// 1. `cargo test` MUTATED a tracked file as a side effect, so every battery
///    left a dirty tree that people learned to discard — discarding the correct
///    regeneration with it.
/// 2. Nothing ever compared committed against regenerated, so the committed
///    bindings could be arbitrarily wrong while the battery was green. They
///    were: the file had no `unserved` field at all, and any `cargo test`
///    rewrote it into a state that did not compile.
///
/// A CI guard for exactly this DOES exist — `wire-types-no-diff` in
/// `.github/workflows/ops-console-embed.yml`, which regenerates and asserts no
/// git diff. Its comment even says the two guards are "kept separate so there is
/// no write-then-assert contradiction", so whoever wrote it saw the trap
/// precisely. But GitHub Actions is disabled on this repository, so the
/// asserting half has never run, while the writing half runs in every local
/// battery. The safety property depended entirely on a lane that is off.
///
/// So the assertion moves here, where it runs. Default: regenerate in memory,
/// compare, and fail WITHOUT writing — a write-then-fail would pass on the
/// second run whether or not anyone committed, turning a gate into a one-shot
/// warning and leaving the dirty tree behind. Writing happens only under
/// [`UPDATE_VAR`].
///
/// # Errors
///
/// Returns an error when the bindings cannot be generated, when the committed
/// file cannot be read or written, or when the committed file differs from the
/// regenerated output.
#[test]
fn export_ops_console_wire_types() -> Result<(), Box<dyn std::error::Error>> {
    let generated = ops_console_wire_types()?;
    let output_path = ops_console_generated_index_path();

    if std::env::var_os(UPDATE_VAR).is_some() {
        fs::write(&output_path, &generated)?;
        return Ok(());
    }

    // `read_to_string` also covers the file being absent, which is the same
    // failure with the same remedy: the committed bindings are not what the
    // exporter produces.
    let committed = fs::read_to_string(&output_path).unwrap_or_default();
    if committed == generated {
        return Ok(());
    }
    Err(format!(
        "the committed ops-console bindings are STALE: `{}` does not match what the \
         exporter produces.\n\
         Nothing was written — regenerate and commit the result:\n    {REGENERATE_COMMAND}\n\
         (committed {} bytes, exporter produces {} bytes)",
        output_path.display(),
        committed.len(),
        generated.len(),
    )
    .into())
}

/// Names declared by hand in the output rather than by a `push_type` call.
///
/// `Namespace` is a bare alias with no Rust type behind it, so ts-rs has nothing
/// to export for it and it is written as a literal below. Anything added here
/// must be genuinely emitted by the literal pushes, or the dependency check
/// stops meaning anything.
const MANUALLY_DECLARED: [&str; 1] = ["Namespace"];

/// The emitter's accumulating state: the text so far, plus the two name sets
/// reconciled at the end.
struct Pipeline {
    config: Config,
    output: String,
    /// Every type this pipeline DECLARES.
    exported: BTreeSet<String>,
    /// Every type those declarations REFERENCE, per ts-rs's own dependency
    /// graph.
    required: BTreeSet<String>,
}

/// Emit the display-name attribute KEY (#211) — a value, not a type.
///
/// The console reads a display name out of a search-attribute map by this
/// key, so the key is part of the wire contract even though ts-rs has no type
/// to derive it from. Emitting it here means there is ONE declaration of it in
/// the world: renaming [`crate::DISPLAY_NAME_ATTRIBUTE`] makes the committed
/// bindings stale, which fails `export_ops_console_wire_types` in the lane that
/// renamed it, and regenerating carries the new key into TypeScript with no
/// hand edit. A mirrored literal on the TS side would instead fail SILENTLY —
/// every name would simply stop rendering.
///
/// It registers no name in the pipeline's export/require reconciliation because
/// it declares no type: nothing can reference a `const` in a type position.
/// Written with plain `push_str` rather than a formatted write, so producing
/// the line cannot fail and the emitted text is exactly the declared key: the
/// key is a bare dotted identifier with nothing a TypeScript string literal
/// would need escaped, which `the_display_name_key_needs_no_escaping` holds
/// true rather than assumes.
fn push_display_name_attribute(pipeline: &mut Pipeline) {
    pipeline
        .output
        .push_str("export const DISPLAY_NAME_ATTRIBUTE = \"");
    pipeline.output.push_str(crate::DISPLAY_NAME_ATTRIBUTE);
    pipeline.output.push_str("\";\n\n");
}

fn ops_console_wire_types() -> Result<String, ts_rs::ExportError> {
    let mut pipeline = Pipeline {
        config: Config::new().with_out_dir(".").with_large_int("number"),
        output: String::from(GENERATED_HEADER),
        exported: BTreeSet::from(MANUALLY_DECLARED.map(String::from)),
        required: BTreeSet::new(),
    };

    push_type::<WorkflowId>(&mut pipeline)?;
    push_type::<RunId>(&mut pipeline)?;
    push_type::<PackageVersion>(&mut pipeline)?;
    push_type::<ScheduleId>(&mut pipeline)?;
    push_type::<ActivityId>(&mut pipeline)?;
    push_type::<TimerIdKind>(&mut pipeline)?;
    push_type::<TimerId>(&mut pipeline)?;
    push_type::<TimerCancelCause>(&mut pipeline)?;
    pipeline
        .output
        .push_str("export type Namespace = string;\n\n");
    push_display_name_attribute(&mut pipeline);
    push_type::<ContentType>(&mut pipeline)?;
    push_type::<PayloadElision>(&mut pipeline)?;
    push_type::<Payload>(&mut pipeline)?;
    push_type::<TriggerSpec>(&mut pipeline)?;
    push_type::<OverlapPolicy>(&mut pipeline)?;
    push_type::<CatchUpPolicy>(&mut pipeline)?;
    push_type::<ScheduleConfig>(&mut pipeline)?;
    push_type::<WorkflowError>(&mut pipeline)?;
    push_type::<ActivityErrorKind>(&mut pipeline)?;
    push_type::<ActivityError>(&mut pipeline)?;
    push_type::<WorkflowStatus>(&mut pipeline)?;
    push_type::<WorkflowFilter>(&mut pipeline)?;
    push_type::<WorkflowSummary>(&mut pipeline)?;
    push_type::<SearchAttributeType>(&mut pipeline)?;
    push_type::<SearchAttributeValue>(&mut pipeline)?;
    push_type::<EventEnvelope>(&mut pipeline)?;
    push_type::<WithTimeoutOutcome>(&mut pipeline)?;
    push_type::<Event>(&mut pipeline)?;
    push_type::<UnservedActivity>(&mut pipeline)?;
    push_type::<RunGeneration>(&mut pipeline)?;
    push_type::<DescribeWorkflowResponse>(&mut pipeline)?;

    // WS3 cluster real-time channel wire types. The aion-proto frame envelopes
    // (StreamedClusterEvent etc.) are intentionally NOT exported here — like StreamedEvent on the
    // workflow path, the outer frame wrappers are hand-decoded on the TS side; only these inner
    // aion-core payload types cross the ts-rs boundary.
    push_type::<ClusterEventMeta>(&mut pipeline)?;
    push_type::<WorkerTransport>(&mut pipeline)?;
    push_type::<WorkerDeathReason>(&mut pipeline)?;
    push_type::<DeploymentAssociation>(&mut pipeline)?;
    push_type::<DesiredState>(&mut pipeline)?;
    push_type::<PutOutcome>(&mut pipeline)?;
    push_type::<NamespacePlacementWire>(&mut pipeline)?;
    push_type::<ClusterEvent>(&mut pipeline)?;
    push_type::<ClusterPeer>(&mut pipeline)?;
    push_type::<ClusterShard>(&mut pipeline)?;
    push_type::<ClusterWorker>(&mut pipeline)?;
    push_type::<ClusterDeployment>(&mut pipeline)?;
    push_type::<ClusterSnapshot>(&mut pipeline)?;
    push_type::<ClusterCommand>(&mut pipeline)?;
    push_type::<ClusterStreamError>(&mut pipeline)?;

    // Agent-observability + intervention real-time channel wire types. Like the cluster
    // channel, only these inner aion-core payload types cross the ts-rs boundary; any outer
    // frame envelopes are hand-decoded on the TS side.
    push_type::<MessageRole>(&mut pipeline)?;
    push_type::<ProgressDetail>(&mut pipeline)?;
    push_type::<StopKind>(&mut pipeline)?;
    push_type::<AgentOutcome>(&mut pipeline)?;
    push_type::<ActivityEventKind>(&mut pipeline)?;
    push_type::<ActivityEvent>(&mut pipeline)?;
    push_type::<InjectPriority>(&mut pipeline)?;
    push_type::<ApprovalDecision>(&mut pipeline)?;
    push_type::<InterventionPrimitive>(&mut pipeline)?;
    push_type::<InterventionKind>(&mut pipeline)?;
    push_type::<InterventionCommand>(&mut pipeline)?;
    push_type::<InterventionCapabilities>(&mut pipeline)?;
    push_type::<InterventionOutcome>(&mut pipeline)?;

    // The live describe join (`POST /workflows/describe-live`). Pushed after the
    // observability + intervention types because it composes them: an attempt's
    // liveness carries `InterventionCapabilities` and its transcript tail
    // carries `ActivityEvent`.
    push_type::<StepState>(&mut pipeline)?;
    push_type::<OpenStep>(&mut pipeline)?;
    push_type::<AttemptLiveness>(&mut pipeline)?;
    push_type::<HeartbeatNote>(&mut pipeline)?;
    push_type::<TranscriptTail>(&mut pipeline)?;
    push_type::<LiveAttempt>(&mut pipeline)?;
    push_type::<CurrentStep>(&mut pipeline)?;
    push_type::<TranscriptStreamHead>(&mut pipeline)?;
    push_type::<DescribeLiveResponse>(&mut pipeline)?;

    assert_every_dependency_is_exported(&pipeline);
    Ok(pipeline.output)
}

/// Every type the emitted declarations reference must ALSO be declared here.
///
/// The required set is ts-rs's own `dependencies()` for each pushed type, so it
/// is derived from the same graph the emitter walks rather than from a second
/// list somebody has to remember to update. A name in `required` but not in
/// `exported` is exactly the `error TS2304: Cannot find name` the console's
/// typecheck reports, caught here instead — in the Rust battery that changed the
/// type, by the person who changed it.
///
/// # Panics
///
/// Panics naming every missing type. A generated file that cannot compile is not
/// a warning: emitting it would hand a broken surface to the console and to
/// every consumer of these bindings.
fn assert_every_dependency_is_exported(pipeline: &Pipeline) {
    let missing = pipeline
        .required
        .difference(&pipeline.exported)
        .cloned()
        .collect::<Vec<_>>();
    assert!(
        missing.is_empty(),
        "the ops-console bindings reference {} type(s) they never declare: {}. \
         Add a `push_type::<T>` call for each in `ops_console_wire_types`; without it the \
         generated index.ts fails to compile with `Cannot find name`.",
        missing.len(),
        missing.join(", "),
    );
}

fn push_type<T>(pipeline: &mut Pipeline) -> Result<(), ts_rs::ExportError>
where
    T: TS + 'static,
{
    let declaration = T::export_to_string(&pipeline.config)?;
    for line in strip_ts_rs_prelude(&declaration).lines() {
        pipeline.output.push_str(line.trim_end());
        pipeline.output.push('\n');
    }
    // Separate declarations after canonicalizing ts-rs's trailing spaces.
    pipeline.output.push('\n');
    pipeline.exported.insert(T::ident(&pipeline.config));
    for dependency in T::dependencies(&pipeline.config) {
        pipeline.required.insert(dependency.ts_name);
    }
    Ok(())
}

fn strip_ts_rs_prelude(declaration: &str) -> &str {
    let without_header = declaration
        .strip_prefix(TS_RS_HEADER)
        .unwrap_or(declaration);

    without_header
        .find("\nexport ")
        .map_or(without_header, |export_start| {
            &without_header[export_start + 1..]
        })
}

fn ops_console_generated_index_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join(OPS_CONSOLE_GENERATED_DIR)
        .join("index.ts")
}
